import os, json, glob, math
import numpy as np

# Analysis-only submission: define test() to run without training.
def _load_json(path):
    with open(path, "r") as f:
        return json.load(f)

def _maybe(path):
    return os.path.exists(path)

def _monotonicity_violation(x):
    # sum of negative diffs when enforcing non-decreasing (as magnitude)
    diffs = np.diff(x)
    return float(np.sum(np.clip(-diffs, 0, None)))

def _slope_energy(x):
    diffs = np.diff(x)
    return float(np.mean(diffs**2))

def _safe_mean(xs, axis=0):
    xs = [np.asarray(x) for x in xs if x is not None]
    if not xs:
        return None
    return np.mean(np.stack(xs, axis=0), axis=axis)

def _read_gamma_trials(base_dir, trials):
    gammas = []
    for tr in trials:
        path = os.path.join(base_dir, f"trial_{tr}.json")
        if not _maybe(path):
            continue
        data = _load_json(path)
        # accept either keys "gamma" or "gamma_t"; prefer lists
        g = data.get("gamma") or data.get("gamma_t")
        if g is None:
            continue
        g = np.array(g, dtype=np.float32)
        gammas.append(g)
    return gammas

def _read_per_condition_mae(base_dir, trials):
    pc = []
    for tr in trials:
        path = os.path.join(base_dir, f"trial_{tr}.json")
        if not _maybe(path):
            continue
        data = _load_json(path)
        # expect dict like {"condN": {"step_mae": [..]}, ...}
        per = {}
        for k, v in data.items():
            if isinstance(v, dict) and "step_mae" in v:
                per[k] = np.array(v["step_mae"], dtype=np.float32)
        if per:
            pc.append(per)
    return pc

def _align_conditions(per_list):
    # Build a union of condition keys and average across trials where present
    keys = set()
    for per in per_list:
        keys |= set(per.keys())
    out = {}
    for k in sorted(keys):
        vals = [per[k] for per in per_list if k in per]
        if not vals:
            continue
        out[k] = np.mean(np.stack(vals, axis=0), axis=0)
    return out

def test():
    # Paths from prior exports
    gamma_dir = "storage/ariadne/analyses/fourier_learn_gamma_export_v2"
    pc_dir = "storage/ariadne/analyses/fourier_learn_gamma_per_condition"
    out_path = "storage/ariadne/analyses/fourier_learn_gamma_consolidated.json"
    trials_main = [42, 43, 44, 45]  # BASE_SEED=42 seeds {42,43,44} + any extra
    # Load learned gamma profiles
    gammas = _read_gamma_trials(gamma_dir, trials_main)
    if not gammas:
        print("No gamma exports found; aborting.")
        return {"ok": False, "reason": "no_gamma_exports"}
    g_mean = _safe_mean(gammas)
    g_std = np.std(np.stack(gammas, axis=0), axis=0)
    mono_v = _monotonicity_violation(g_mean)
    slope_e = _slope_energy(g_mean)
    tail_mean = float(np.mean(g_mean[-4:]))
    peak_val = float(np.max(g_mean))
    peak_idx = int(np.argmax(g_mean))
    # Per-condition aggregation
    pc_list = _read_per_condition_mae(pc_dir, trials_main)
    cond_agg = _align_conditions(pc_list)
    # Difficulty (per-step) as mean across available conditions
    step_diff = None
    corr_gamma_diff = None
    if cond_agg:
        step_mat = np.stack([v for v in cond_agg.values()], axis=0)  # (C, T)
        step_diff = np.mean(step_mat, axis=0)  # (T,)
        # Correlation between gamma and (neg) difficulty? We use +corr with difficulty
        a = (g_mean - g_mean.mean())
        b = (step_diff - step_diff.mean())
        denom = (np.linalg.norm(a) * np.linalg.norm(b) + 1e-12)
        corr_gamma_diff = float(np.dot(a, b) / denom) if denom > 0 else None
    # Package
    result = {
        "ok": True,
        "trials": trials_main,
        "gamma_mean": g_mean.tolist(),
        "gamma_std": g_std.tolist(),
        "stats": {
            "monotonicity_violation": mono_v,
            "slope_energy": slope_e,
            "tail_mean_last4": tail_mean,
            "peak": {"value": peak_val, "t_index": peak_idx}
        },
        "per_condition_keys": sorted(list(cond_agg.keys())),
        "corr_gamma_vs_step_difficulty": corr_gamma_diff,
    }
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(result, f, indent=2)
    print("Wrote:", out_path)
    print("corr_gamma_vs_step_difficulty:", corr_gamma_diff)
    return result
